+  private long instanceSize(long stackSizeInWords) {
+    long sizeInWords = getSizeHelper() + stackSizeInWords + gcDataSize(stackSizeInWords);
+    return Oop.alignObjectSize(sizeInWords * VM.getVM().getAddressSize());
+  }
